// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // rely on a user that is not the deployer (0xdead)
        address user = address(0xdead);
        // deployer calls rely(user)
        vm.prank(address(this));
        c.rely(user);
        // now have user call allowance(address,address) — auth modifier checks wards[msg.sender]
        // in reference: wards[user]=1, auth passes, call succeeds.
        // in bug: wards[user]=0, auth fails, call reverts.
        vm.prank(user);
        bool ok;
        try c.allowance(address(0), address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

