import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Use a distinct unprivileged user
        address user = address(0x1234);

        // First, rely on user so they become authorized
        c.rely(user);

        // Then, deny the user
        vm.prank(user);
        c.deny(user);

        // Now call allowance from user – this triggers the delegatecall to share
        // which will read wards (autogenerated getter)
        c.allowance(user, address(0x5678));

        // Assert that wards[user] is 0 (as the correct deny sets it to 0)
        // In the buggy version, deny sets it to 1, so this assertion fails
        assertTrue(c.wards(user) == 0);
    }
}

