contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Setup: an unprivileged user (not the deployer)
        address user = address(0x1234);

        // Step 1: user has no wards entry yet (defaults to 0)
        // Step 2: user calls public/external function allowance (any non-auth function) to set msg.sender
        vm.prank(user);
        c.allowance(address(0), address(0));

        // Step 3: user calls deny on themselves – reference sets wards[user]=0, bug sets to 1
        vm.prank(user);
        c.deny(user);

        // Step 4: now try to call an auth-gated function (updatePrice) as the same user
        vm.prank(user);
        // In reference, wards[user] == 0 so updatePrice reverts (Auth/not-authorized)
        // In bug, wards[user] == 1 so it succeeds
        (bool ok, ) = address(c).call(abi.encodeWithSignature("updatePrice(uint128)", 100));
        assertTrue(!ok, "Reference: auth-gated call should revert; bug: it succeeds");
    }
}

