pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deployer (this) is authorized by default (wards[this] = 1).
        // First, deny ourselves to make msg.sender unauthorized (wards[this] = 0).
        c.deny(address(this));
        // Now call allowance(this, 0) which triggers auth modifier.
        // The original require(wards[msg.sender] == 1) will revert because wards[this] = 0.
        // The buggy require(wards[msg.sender] == 0) will pass and the delegatecall
        // to share.approve will set wards[this] = 1 (since the underlying share's
        // approve constructs calldata with bytes20(address(this)), which gets
        // misinterpreted by the auth modifier as setting wards[this] to 1).
        // We capture whether the call reverts.
        bool ok;
        try c.allowance(address(this), address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, the call reverts (ok = false).
        // In the bug, the call succeeds (ok = true).
        assertTrue(!ok);
    }
}

