    function testRegression_property() public {
        // Deploy a malicious share contract that calls updatePrice on any call
        address share = address(new MaliciousShare(address(c)));
        // Re-deploy C with the malicious share (we cannot change setUp, so we just set the share storage directly? No, we must use the given constructor.
        // Instead: we directly interact with the already deployed C, but its share is address(this). We need to make address(this) behave as the malicious contract.
