import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Ensure totalSupply() returns 100
        // Since share is address(this), we directly call share.mint to set supply
        vm.prank(address(this));
        c.mint(address(this), 100);
        // Now totalSupply() = 100, totalAssets() should differ
        uint256 ref = c.totalAssets();
        // If buggy, it would return 0; if reference, it returns something else (here 100 from mock)
        assertTrue(ref != 0, "totalAssets should not be zero when totalSupply is 100");
    }
